import static org.junit.Assert.assertNotNull;

public class CpioArchiveInputStream_CpioArchiveInputStream_TriageGen1Test {

    @Test
    public void testConstructorWithAllParameters() throws IOException {
        byte[] data = new byte[0];
        InputStream in = new ByteArrayInputStream(data);
        int blockSize = 1024;
        String encoding = "UTF-8";

        CpioArchiveInputStream cis = new CpioArchiveInputStream(in, blockSize, encoding);

        assertNotNull(cis);
        cis.close();
    }












}

